    private final String dark;
    private final String pumpkin;
    private final String candle;
    private final String lantern;

    GuiHeads(String dark, String pumpkin, String candle, String lantern) {
        this.dark = dark;
        this.pumpkin = pumpkin;
        this.candle = candle;
        this.lantern = lantern;
    }

    public String texture(GuiTheme theme) {
        return switch (theme) {
            case PUMPKIN -> pumpkin;
            case CANDLE -> candle;
            case LANTERN -> lantern;
            default -> dark;
        };
    }

